        data = append(data, average)
        labels = append(labels, state)
    }
    p := plot.New()
    p.Title.Text = "Average Cost of a Movie Ticket by State"
    p.Y.Label.Text = "Price ($)"
    bars, err := plotter.NewBarChart(data, vg.Points(50))
    if err != nil {
        fmt.Println(err)
        return
    }
    bars.Color = plotutil.Color(0)
    p.Add(bars)
    p.NominalX(labels...)
    if err := p.Save(6*vg.Inch, 4*vg.Inch, "movie_ticket_prices.png"); err != nil {
        fmt.Println(err)
        return
    }
}
func parseFloat(s string) float64 {
    f, _ := strconv.ParseFloat(s, 64)
    return f
}
```
This code should generate a bar chart of the average cost of a movie ticket by state based on the data in the excel table. The chart will be saved as a PNG file named `movie_ticket_prices.png`.

