#include <iostream>
#include <vector>
using namespace std;
double calculateAverage(vector<double> temperatures) {
    double sum = 0;
    for (int i = 0; i < temperatures.size(); i++) {
        sum += temperatures[i];
    }
    return sum / temperatures.size();
}
int main() {
